43: public final class ALDynamicLibraryBundleInfo implements DynamicLibraryBundleInfo  {
44:     private static final List<String> glueLibNames;
45:     static {
46:         SecurityUtil.doPrivileged(new PrivilegedAction<Object>() {
47:             @Override
48:             public Object run() {
49:                 Platform.initSingleton();
50: 
51:                 if( TempJarCache.isInitialized(true) ) {
52:                    // only: joal.jar -> joal-natives-<os.and.arch>.jar
53:                    JNILibLoaderBase.addNativeJarLibs(new Class<?>[] { jogamp.openal.Debug.class }, null );
54:                 }
55:                 return null;
56:             }
57:         });
58: 
59:         glueLibNames = new ArrayList<String>();
60:         glueLibNames.add("joal");
61:     }
62: 
63:     protected ALDynamicLibraryBundleInfo() {
64:     }
65: 
66:     /**
67:      * <p>
68:      * Returns <code>true</code>,
69:      * since we might load the library and allow symbol access to subsequent libs.
70:      * </p>
71:      */
72:     @Override
73:     public final boolean shallLinkGlobal() { return true; }
74: 
75:     /**
76:      * {@inheritDoc}
77:      * <p>
78:      * Returns <code>false</code>.
79:      * </p>
80:      */
81:     @Override
82:     public final boolean shallLookupGlobal() { return false; }
83: 
84:     @Override
85:     public final List<String> getGlueLibNames() {
86:         return glueLibNames;
87:     }
88: 
89:     @Override
90:     public final boolean searchToolLibInSystemPath() {
91:         return true;
92:     }
93: 
94:     @Override
95:     public final boolean searchToolLibSystemPathFirst() {
96:         return ALFactory.PREFER_SYSTEM_OPENAL;
97:     }
98: 
99:     @Override
100:     public final List<List<String>> getToolLibNames() {
101:         final List<List<String>> libNamesList = new ArrayList<List<String>>();
102: 
103:         final List<String> alSystemLibNames = new ArrayList<String>();
104:         {
105:             // this is the default AL lib name, according to the spec
106:             alSystemLibNames.add("libopenal.so.1"); // unix
107:             alSystemLibNames.add("OpenAL32"); // windows
108:             alSystemLibNames.add("OpenAL"); // OSX
109: 
110:             // try this one as well, if spec fails
111:             alSystemLibNames.add("libOpenAL.so.1");
112:             alSystemLibNames.add("libopenal.so");
113:             alSystemLibNames.add("libOpenAL.so");
114:         }
115:         final List<String> alSoftLibNames = new ArrayList<String>();
116:         {
117:             // These names are in use by the bundled OpenAL-soft, also generic ones
118:             alSoftLibNames.add("openal");
119:             alSoftLibNames.add("OpenAL");
120:             alSoftLibNames.add("OpenAL32");
121:             // This name is in use by the (installed if any) OpenAL-soft
122:             alSoftLibNames.add("soft_oal");
123:         }
124: 
125:         final List<String> alLibNames = new ArrayList<String>();
126: 
127:         if( ALFactory.PREFER_SYSTEM_OPENAL ) {
128:             // First test the System OpenAL
129:             alLibNames.addAll(alSystemLibNames);
130: 
131:             // last but not least .. bundled OpenAL-soft
132:             alLibNames.addAll(alSoftLibNames);
133:         } else {
134:             // First test use of the bundled OpenAL-soft
135:             alLibNames.addAll(alSoftLibNames);
136: 
137:             // Then try the System OpenAL
138:             alLibNames.addAll(alSystemLibNames);
139:         }
140:         libNamesList.add(alLibNames);
141: 
142:         return libNamesList;
143:     }
